INSERT INTO plantillas_consentimiento (codigo, titulo, tipo, contenido, version, activo) VALUES ('CONS-QUIR-V1', 'Consentimiento Informado para Exodoncia y Cirugía Oral', 'INFORMADO_PROCEDIMIENTO', 'He sido informado(a) del procedimiento quirúrgico propuesto (extracción o cirugía oral), de sus alternativas, de los riesgos habituales (dolor, inflamación, sangrado, infección, alteraciones de sensibilidad, comunicación con el seno maxilar, fractura de raíces) y de las indicaciones postoperatorias. Autorizo su realización y la anestesia necesaria.', 1, true) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO plantillas_consentimiento (codigo, titulo, tipo, contenido, version, activo) VALUES ('CONS-ENDO-V1', 'Consentimiento Informado para Tratamiento de Conductos (Endodoncia)', 'INFORMADO_PROCEDIMIENTO', 'He sido informado(a) del tratamiento de conductos, de su finalidad (conservar la pieza), de las posibles complicaciones (dolor postoperatorio, fractura de instrumentos, perforaciones, necesidad de retratamiento o de cirugía) y de que la pieza requiere una restauración definitiva posterior. Autorizo el procedimiento.', 1, true) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO plantillas_consentimiento (codigo, titulo, tipo, contenido, version, activo) VALUES ('CONS-ORTO-V1', 'Consentimiento Informado para Ortodoncia y Ortopedia', 'INFORMADO_PROCEDIMIENTO', 'He sido informado(a) del plan de ortodoncia u ortopedia, su duración estimada, los riesgos (descalcificaciones, reabsorción radicular, recidiva) y mi responsabilidad: higiene, uso de elásticos o aparatos indicados y asistencia puntual a los controles mensuales. Autorizo el tratamiento.', 1, true) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO plantillas_consentimiento (codigo, titulo, tipo, contenido, version, activo) VALUES ('CONS-BLANQ-V1', 'Consentimiento Informado para Blanqueamiento Dental', 'INFORMADO_PROCEDIMIENTO', 'He sido informado(a) del blanqueamiento, de que el resultado varía según cada persona, de la posible sensibilidad dental o gingival temporal y de que no actúa sobre restauraciones existentes. Autorizo el procedimiento.', 1, true) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO plantillas_consentimiento (codigo, titulo, tipo, contenido, version, activo) VALUES ('CONS-PROT-V1', 'Consentimiento Informado para Prótesis Dental (removible, fija y carillas)', 'INFORMADO_PROCEDIMIENTO', 'He sido informado(a) del tipo de prótesis o carilla propuesta, del tallado dental necesario en prótesis fijas y carillas, de los periodos de adaptación, del mantenimiento y de que puede requerir ajustes o reposición. Autorizo el tratamiento.', 1, true) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO plantillas_consentimiento (codigo, titulo, tipo, contenido, version, activo) VALUES ('CONS-MENOR-V1', 'Consentimiento Informado para Atención de Menores de Edad', 'INFORMADO_PROCEDIMIENTO', 'Como padre, madre o tutor legal autorizo la atención odontológica del menor indicado, habiendo recibido información sobre el procedimiento, sus riesgos y las indicaciones posteriores, y me comprometo a acompañarlo y a seguir las recomendaciones del odontólogo.', 1, true) ON CONFLICT (codigo) DO NOTHING;
