-- Plantillas de tratamiento: ficha clínica específica por familia de tratamiento, enlazada a los servicios del catálogo.

CREATE TABLE IF NOT EXISTS plantillas_tratamiento (
    codigo       text PRIMARY KEY,
    nombre       text        NOT NULL,
    negocio      text        NOT NULL CHECK (negocio IN ('VILLADENT','VILLAMAX')),
    descripcion  text,
    version      integer     NOT NULL DEFAULT 1,
    esquema      jsonb       NOT NULL,
    activo       boolean     NOT NULL DEFAULT true,
    creado_en    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS servicio_plantilla (
    servicio_id      text PRIMARY KEY REFERENCES servicios_web(id) ON DELETE CASCADE,
    plantilla_codigo text NOT NULL REFERENCES plantillas_tratamiento(codigo)
);

-- Lo que el doctor llena por paciente (y por plan o cita). BORRADOR se edita; CERRADO queda inmutable y se corrige con un registro nuevo.
CREATE TABLE IF NOT EXISTS registros_plantilla (
    id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    paciente_id        uuid        NOT NULL REFERENCES pacientes(id),
    tratamiento_id     uuid        REFERENCES tratamientos(id),
    cita_id            uuid        REFERENCES citas(id),
    plantilla_codigo   text        NOT NULL REFERENCES plantillas_tratamiento(codigo),
    plantilla_version  integer     NOT NULL,
    datos              jsonb       NOT NULL DEFAULT '{}'::jsonb,
    estado             text        NOT NULL DEFAULT 'BORRADOR' CHECK (estado IN ('BORRADOR','CERRADO')),
    corrige_id         uuid        REFERENCES registros_plantilla(id),
    creado_por         uuid        REFERENCES usuarios(id),
    creado_por_nombre  text,
    creado_en          timestamptz NOT NULL DEFAULT now(),
    cerrado_en         timestamptz
);
CREATE INDEX IF NOT EXISTS registros_plantilla_paciente_idx ON registros_plantilla (paciente_id, creado_en DESC);


